/**
 * Recurrence rules. Every rule kind has a closed-form "k-th occurrence ⇄ date" mapping, so
 * ranges are generated by jumping straight to them (no iteration over years of history), and
 * `count` limits are applied by computing the date of the count-th occurrence directly.
 *
 * Semantics (SPEC §4.1):
 *  - Occurrences are rule dates >= start, <= until, and among the first `count` (counted from start).
 *  - Start is an occurrence only if it matches the rule.
 *  - daily:   start + k·interval days.
 *  - weekly:  weekdays in byWeekday, in weeks (Monday-based) whose index from the week containing
 *             start is a multiple of interval.
 *  - monthly: day-of-month of start, clamped to the month's last day (31st → Apr 30, Feb 28/29).
 *  - yearly:  month/day of start; Feb 29 → Feb 28 in non-leap years.
 */
import {
  MAX_EPOCH_DAY,
  civilFromDays,
  daysFromCivil,
  daysInMonth,
  parseYMD,
  toEpochDay,
  fromEpochDay,
  weekdayOfEpochDay,
} from './dates.js';
import { MONTH_SHORT, WEEKDAY_NAMES, WEEKDAY_SHORT, formatDateMedium } from './format.js';
import type { ISODate, Recurrence, Weekday } from './types.js';

const FREQS: ReadonlyArray<Recurrence['freq']> = ['daily', 'weekly', 'monthly', 'yearly'];

/**
 * A rule pre-digested for fast queries. `lastE` folds `until` and `count` into a single inclusive
 * upper bound (epoch day; Infinity when the series never ends).
 */
export interface CompiledRule {
  readonly rule: Recurrence;
  readonly freq: Recurrence['freq'];
  readonly interval: number;
  readonly startE: number;
  readonly sy: number;
  readonly sm: number;
  readonly sd: number;
  /** weekly: sorted Monday-based positions (0 = Mon … 6 = Sun). */
  readonly positions: readonly number[];
  /** weekly: epoch day of the Monday of the week containing start. */
  readonly weekBaseE: number;
  /** weekly: how many rule weekdays of the first week fall before start. */
  readonly firstSkip: number;
  readonly lastE: number;
}

function sanitizeWeekdays(v: unknown): Weekday[] {
  if (!Array.isArray(v)) return [];
  const set = new Set<number>();
  for (const x of v) if (typeof x === 'number' && Number.isInteger(x) && x >= 0 && x <= 6) set.add(x);
  return [...set].sort((a, b) => a - b) as Weekday[];
}

function sanitizeInterval(v: unknown): number {
  return typeof v === 'number' && Number.isFinite(v) && v >= 1 ? Math.floor(v) : 1;
}

function sanitizeCount(v: unknown): number | null {
  return typeof v === 'number' && Number.isFinite(v) && v >= 1 ? Math.floor(v) : null;
}

/** Builds the compiled form ignoring until/count (used to evaluate count limits). */
function compileBase(
  freq: Recurrence['freq'],
  interval: number,
  byWeekday: readonly Weekday[] | null,
  startE: number,
): Omit<CompiledRule, 'rule' | 'lastE'> {
  const [sy, sm, sd] = civilFromDays(startE);
  const startPos = (weekdayOfEpochDay(startE) + 6) % 7;
  const weekBaseE = startE - startPos;
  const positions =
    freq === 'weekly' ? (byWeekday ?? []).map((w) => (w + 6) % 7).sort((a, b) => a - b) : ([] as number[]);
  let firstSkip = 0;
  for (const p of positions) if (p < startPos) firstSkip++;
  return { freq, interval, startE, sy, sm, sd, positions, weekBaseE, firstSkip };
}

type Base = Omit<CompiledRule, 'rule' | 'lastE'>;

/** Epoch day of the k-th (0-based) occurrence, ignoring until/count. Infinity past year 9999. */
function dateOfOrdinal(c: Base, k: number): number {
  if (!Number.isFinite(k) || k < 0) return Infinity;
  switch (c.freq) {
    case 'daily': {
      const e = c.startE + k * c.interval;
      return e > MAX_EPOCH_DAY ? Infinity : e;
    }
    case 'weekly': {
      const K = c.positions.length;
      if (K === 0) return Infinity;
      const m = k + c.firstSkip;
      const p = Math.floor(m / K);
      const pos = c.positions[m - p * K] ?? 0;
      const e = c.weekBaseE + p * c.interval * 7 + pos;
      return e > MAX_EPOCH_DAY ? Infinity : e;
    }
    case 'monthly': {
      const total = c.sm - 1 + k * c.interval;
      const y = c.sy + Math.floor(total / 12);
      if (y > 9999) return Infinity;
      const m = (total % 12) + 1;
      return daysFromCivil(y, m, Math.min(c.sd, daysInMonth(y, m)));
    }
    case 'yearly': {
      const y = c.sy + k * c.interval;
      if (y > 9999) return Infinity;
      return daysFromCivil(y, c.sm, Math.min(c.sd, daysInMonth(y, c.sm)));
    }
  }
}

/** 0-based occurrence ordinal of epoch day `e`, or -1 if `e` is not a rule date (until/count ignored). */
function ordinalOf(c: Base, e: number): number {
  if (e < c.startE) return -1;
  switch (c.freq) {
    case 'daily': {
      const diff = e - c.startE;
      return diff % c.interval === 0 ? diff / c.interval : -1;
    }
    case 'weekly': {
      const off = e - c.weekBaseE;
      const w = Math.floor(off / 7);
      if (w % c.interval !== 0) return -1;
      const r = c.positions.indexOf(off - w * 7);
      if (r < 0) return -1;
      const k = (w / c.interval) * c.positions.length + r - c.firstSkip;
      return k >= 0 ? k : -1;
    }
    case 'monthly': {
      const [y, m, d] = civilFromDays(e);
      const md = (y - c.sy) * 12 + (m - c.sm);
      if (md < 0 || md % c.interval !== 0) return -1;
      return d === Math.min(c.sd, daysInMonth(y, m)) ? md / c.interval : -1;
    }
    case 'yearly': {
      const [y, m, d] = civilFromDays(e);
      const yd = y - c.sy;
      if (yd < 0 || yd % c.interval !== 0 || m !== c.sm) return -1;
      return d === Math.min(c.sd, daysInMonth(y, m)) ? yd / c.interval : -1;
    }
  }
}

/**
 * Cleans a rule for storage/evaluation. Always returns every key (null when unused) because
 * Firestore rejects `undefined`.
 *  - freq: unknown → 'daily' (a broken rule still shows up rather than vanishing).
 *  - interval: integer >= 1 (default 1).
 *  - byWeekday (weekly only): sorted unique 0…6, default [weekday(start)]; null for other freqs.
 *  - until/count are mutually exclusive. Invalid until → null; count < 1 → null (never ends).
 *    If BOTH are present (corrupt data), the LESS restrictive one is kept so no planned
 *    occurrence disappears. An until before start is raised to start (otherwise moving a
 *    series start past its end would silently hide the whole series).
 */
export function normalizeRecurrence(rule: Recurrence, start: ISODate): Recurrence {
  const startE = toEpochDay(start);
  const freq: Recurrence['freq'] = FREQS.includes(rule?.freq) ? rule.freq : 'daily';
  const interval = sanitizeInterval(rule?.interval);
  let byWeekday: Weekday[] | null = null;
  if (freq === 'weekly') {
    byWeekday = sanitizeWeekdays(rule?.byWeekday);
    if (byWeekday.length === 0) byWeekday = [weekdayOfEpochDay(startE)];
  }
  let until: ISODate | null = typeof rule?.until === 'string' && parseYMD(rule.until) ? rule.until : null;
  if (until !== null && until < start) until = start;
  let count = sanitizeCount(rule?.count);
  if (until !== null && count !== null) {
    const base = compileBase(freq, interval, byWeekday, startE);
    const lastByCount = dateOfOrdinal(base, count - 1);
    if (lastByCount > toEpochDay(until)) until = null;
    else count = null;
  }
  return { freq, interval, byWeekday, until, count };
}

/**
 * Normalizes and pre-computes a rule for repeated queries against one series start.
 * Prefer this over the convenience functions when evaluating many dates of the same series.
 */
export function compileRecurrence(rule: Recurrence, start: ISODate): CompiledRule {
  const n = normalizeRecurrence(rule, start);
  const startE = toEpochDay(start);
  const base = compileBase(n.freq, n.interval, n.byWeekday ?? null, startE);
  let lastE = n.until != null ? toEpochDay(n.until) : Infinity;
  if (n.count != null) lastE = Math.min(lastE, dateOfOrdinal(base, n.count - 1));
  return { ...base, rule: n, lastE };
}

/** True if epoch day `e` is an occurrence of the compiled rule (until/count honored). */
export function compiledIsRuleDate(c: CompiledRule, e: number): boolean {
  return e >= c.startE && e <= c.lastE && ordinalOf(c, e) >= 0;
}

/**
 * Calls `fn(epochDay)` for each occurrence in [loE, hiE] in ascending order; stops early when `fn`
 * returns false. Cost is proportional to the number of occurrences emitted.
 */
export function compiledForEach(c: CompiledRule, loE: number, hiE: number, fn: (e: number) => boolean | void): void {
  const lo = Math.max(loE, c.startE);
  const hi = Math.min(hiE, c.lastE, MAX_EPOCH_DAY);
  if (lo > hi) return;
  switch (c.freq) {
    case 'daily': {
      const k0 = Math.ceil((lo - c.startE) / c.interval);
      for (let e = c.startE + k0 * c.interval; e <= hi; e += c.interval) if (fn(e) === false) return;
      return;
    }
    case 'weekly': {
      if (c.positions.length === 0) return;
      let w = Math.floor((lo - c.weekBaseE) / 7);
      const rem = w % c.interval;
      if (rem !== 0) w += c.interval - rem;
      for (let base = c.weekBaseE + w * 7; base <= hi; base += c.interval * 7) {
        for (const pos of c.positions) {
          const e = base + pos;
          if (e < lo) continue;
          if (e > hi) return;
          if (fn(e) === false) return;
        }
      }
      return;
    }
    case 'monthly':
    case 'yearly': {
      const [ly, lm] = civilFromDays(lo);
      const units = c.freq === 'monthly' ? (ly - c.sy) * 12 + (lm - c.sm) : ly - c.sy;
      let k = Math.max(0, Math.floor(units / c.interval));
      for (;;) {
        const e = dateOfOrdinal(c, k);
        if (e > hi) return;
        if (e >= lo && fn(e) === false) return;
        k++;
      }
    }
  }
}

/** Rule dates in [from, to] (inclusive), >= start, honoring until/count (count counted from start). */
export function occurrenceDates(rule: Recurrence, start: ISODate, from: ISODate, to: ISODate): ISODate[] {
  const c = compileRecurrence(rule, start);
  const out: ISODate[] = [];
  compiledForEach(c, toEpochDay(from), toEpochDay(to), (e) => {
    out.push(fromEpochDay(e));
  });
  return out;
}

export function isRuleDate(rule: Recurrence, start: ISODate, date: ISODate): boolean {
  const p = parseYMD(date);
  if (!p) return false;
  return compiledIsRuleDate(compileRecurrence(rule, start), daysFromCivil(p[0], p[1], p[2]));
}

/** First rule date >= max(onOrAfter, start), or null when the series has ended. */
export function nextRuleDate(rule: Recurrence, start: ISODate, onOrAfter: ISODate): ISODate | null {
  const c = compileRecurrence(rule, start);
  let found = -Infinity;
  compiledForEach(c, toEpochDay(onOrAfter), Infinity, (e) => {
    found = e;
    return false;
  });
  return found === -Infinity ? null : fromEpochDay(found);
}

function ordinal(n: number): string {
  const mod100 = n % 100;
  if (mod100 >= 11 && mod100 <= 13) return `${n}th`;
  switch (n % 10) {
    case 1:
      return `${n}st`;
    case 2:
      return `${n}nd`;
    case 3:
      return `${n}rd`;
    default:
      return `${n}th`;
  }
}

/** Monday-first display order of weekdays. */
function mondayFirst(days: readonly Weekday[]): Weekday[] {
  return [...days].sort((a, b) => ((a + 6) % 7) - ((b + 6) % 7));
}

/**
 * "Every day" | "Every 2 days" | "Every weekday" | "Every week on Thursday" | "Every week on Mon, Wed" |
 * "Every 2 weeks on Mon" | "Every month on the 19th" | "Every year on Nov 19"
 * (+ ", until Dec 31, 2026" | ", 10 times"). A single weekday is spelled out only for plain weekly rules.
 */
export function describeRecurrence(rule: Recurrence, start: ISODate): string {
  const n = normalizeRecurrence(rule, start);
  const [, sm, sd] = civilFromDays(toEpochDay(start));
  const every = (unit: string): string => (n.interval === 1 ? `Every ${unit}` : `Every ${n.interval} ${unit}s`);
  let text: string;
  switch (n.freq) {
    case 'daily':
      text = every('day');
      break;
    case 'weekly': {
      const days = mondayFirst(n.byWeekday ?? []);
      if (n.interval === 1 && days.join(',') === '1,2,3,4,5') {
        text = 'Every weekday';
      } else if (n.interval === 1 && days.length === 1) {
        text = `Every week on ${WEEKDAY_NAMES[days[0] ?? 0]}`;
      } else {
        text = `${every('week')} on ${days.map((d) => WEEKDAY_SHORT[d]).join(', ')}`;
      }
      break;
    }
    case 'monthly':
      text = `${every('month')} on the ${ordinal(sd)}`;
      break;
    case 'yearly':
      text = `${every('year')} on ${MONTH_SHORT[sm - 1]} ${sd}`;
      break;
  }
  if (n.until != null) text += `, until ${formatDateMedium(n.until)}`;
  else if (n.count != null) text += `, ${n.count} ${n.count === 1 ? 'time' : 'times'}`;
  return text;
}
